def replace_between(source: str, start_marker: str, end_marker: str, replacement: str) -> str:
    start = source.index(start_marker)
    end = source.index(end_marker, start)
    return source[:start] + replacement + source[end:]


helper = "function buildVerifiedBoundarySegments(collection,radius=1.00062){const pos=[];for(const f of collection?.features??[])for(const line of lineStrings(f)){if(!Array.isArray(line)||line.length<2)continue;for(let i=0;i<line.length-1;i++){const a=line[i],b=line[i+1];if(!a||!b)continue;const p1=latLonVector(a[1],a[0],radius),p2=latLonVector(b[1],b[0],radius);pos.push(p1.x,p1.y,p1.z,p2.x,p2.y,p2.z)}}return pos}\n"
if 'function buildVerifiedBoundarySegments(' not in text:
    marker = 'function makeWideLines('
    idx = text.index(marker)
    text = text[:idx] + helper + text[idx:]

